// ALL expected values below are golden fixtures generated by executing the
// ORIGINAL EloGuard lib/review-core.js (plus the verbatim content.js
// clockFeaturesForSide) in node over the exact same inputs
// (scratchpad/gen-strength-fixtures.cjs). Floats are asserted to 1e-9,
// integers exactly.

const cp = (value: number): EvalScore => ({ cp: value });
const mate = (value: number): EvalScore => ({ mate: value });

function close(actual: number | null | undefined, expected: number) {
    expect(actual).not.toBeNull();
    expect(actual).toBeCloseTo(expected, 9);
}

// Rounds to 9 decimals so float goldens compare exactly (the port is an
// operation-for-operation copy, so values are expected to be bit-identical).
function norm(value: number | null | undefined): number | null {
    return typeof value === "number" ? Number(value.toFixed(9)) : null;
}

function expectPhase(
    actual: GamePhaseStats | undefined,
    expected: {
        accuracy: number | null;
        acpl: number | null;
        scoredCount: number;
        complexity: number;
    },
) {
    expect(actual).toBeDefined();
    const phase = actual as GamePhaseStats;
    expect({
        accuracy: norm(phase.accuracy),
        acpl: norm(phase.acpl),
        scoredCount: phase.scoredCount,
        complexity: norm(phase.complexity),
    }).toEqual({
        accuracy: norm(expected.accuracy),
        acpl: norm(expected.acpl),
        scoredCount: expected.scoredCount,
        complexity: norm(expected.complexity),
    });
}

// ---------------------------------------------------------------------------
// timeClassOf
// ---------------------------------------------------------------------------

describe("timeClassOf", () => {
    test("matches review-core pool boundaries", () => {
        expect(timeClassOf({ base: 600, inc: 0 })).toBe("rapid");
        expect(timeClassOf({ base: 180, inc: 0 })).toBe("blitz");
        expect(timeClassOf({ base: 179, inc: 0 })).toBe("bullet");
        expect(timeClassOf({ base: 60, inc: 3 })).toBe("blitz");
        expect(timeClassOf({ base: 0, inc: 0 })).toBe("bullet");
        expect(timeClassOf({ base: 5400, inc: 0 })).toBe("classical");
        expect(timeClassOf({ base: 900, inc: 10 })).toBe("rapid");
        expect(timeClassOf(null)).toBe("rapid");
        expect(timeClassOf("bullet")).toBe("bullet");
        expect(timeClassOf("classical")).toBe("classical");
    });
});

