describe("estimateRating / gamePerformance / anchored estimators", () => {
    for (const blob of statBlobs) {
        test(`golden fixture: ${blob.name}`, () => {
            expect(estimateRating(blob.stats, blob.tc)).toEqual(blob.estimateRating);
            expect(estimateRating(blob.stats, blob.tc, "opening")).toEqual(
                blob.estimateRatingOpening,
            );
            expect(estimateRating(blob.stats, blob.tc, "endgame")).toEqual(
                blob.estimateRatingEndgame,
            );
            expect(gamePerformance(blob.stats, blob.tc, blob.rating)).toEqual(blob.gamePerformance);
            expect(gamePerformance(blob.stats, blob.tc, null)).toBeNull();
            expect(
                anchoredStrength(blob.skillFeature, blob.stats.scoredCount, blob.pool, blob.rating),
            ).toEqual(blob.anchoredStrength);
            expect(
                anchoredStrength(
                    blob.skillFeature,
                    blob.stats.scoredCount,
                    blob.pool,
                    blob.rating,
                    -54,
                ),
            ).toEqual(blob.anchoredStrengthOffset);
            expect(
                anchoredPerformance(
                    blob.perfFeature,
                    blob.stats.scoredCount,
                    blob.pool,
                    blob.rating,
                ),
            ).toEqual(blob.anchoredPerformance);
            expect(
                anchoredPerformance(null, blob.stats.scoredCount, blob.pool, blob.rating),
            ).toBeNull();
            expect(
                anchoredPerformance(blob.perfFeature, blob.stats.scoredCount, blob.pool, null),
            ).toBeNull();
        });
    }

    test("estimateRating returns null without scored accuracy", () => {
        const empty: GameQualityStats = {
            accuracy: null,
            acpl: null,
            scoredCount: 0,
            complexity: 4.5,
            bookMoves: 0,
            blunderRate: 0,
            fastRate: null,
            scramble: null,
            analysisDepth: null,
        };
        expect(estimateRating(empty, { base: 600, inc: 0 })).toBeNull();
        expect(gamePerformance(empty, { base: 600, inc: 0 }, 1500)).toBeNull();
    });

    test("anchored estimator edge fixtures", () => {
        expect(anchoredStrength(1650.5, 120, "blitz", 1500)).toEqual({
            strength: 1505,
            delta: 5,
            baseline: 1500,
            uncertainty: 150,
            lambda: 0.101,
            pool: "blitz",
        });
        expect(anchoredStrength(1200, 4, "bullet", 900, -54)).toEqual({
            strength: 900,
            delta: 0,
            baseline: 900,
            uncertainty: 175,
            lambda: 0.004,
            pool: "bullet",
        });
        expect(anchoredStrength(2960.25, 30, "rapid", 2900)).toEqual({
            strength: 2925,
            delta: 25,
            baseline: 2900,
            uncertainty: 175,
            lambda: 0.027,
            pool: "rapid",
        });
        expect(anchoredStrength(1500, 12, "classical", 1600)).toEqual({
            strength: 1595,
            delta: -5,
            baseline: 1600,
            uncertainty: 175,
            lambda: 0.011,
            pool: "classical",
        });
        expect(anchoredStrength(700, 300, "rapid", 350)).toEqual({
            strength: 210,
            delta: -140,
            baseline: 350,
            uncertainty: 150,
            lambda: 0.219,
            pool: "rapid",
        });
        expect(anchoredPerformance(1700, 35, "blitz", 1450)).toEqual({
            strength: 1460,
            delta: 10,
            baseline: 1450,
            uncertainty: 250,
            pool: "blitz",
        });
        expect(anchoredPerformance(900.75, 10, "bullet", 700)).toEqual({
            strength: 670,
            delta: -30,
            baseline: 700,
            uncertainty: 500,
            pool: "bullet",
        });
        expect(anchoredPerformance(2600, 80, "rapid", 2450)).toEqual({
            strength: 2515,
            delta: 65,
            baseline: 2450,
            uncertainty: 200,
            pool: "rapid",
        });
        expect(anchoredPerformance(2100, 1, "classical", 2985)).toEqual({
            strength: 2650,
            delta: -335,
            baseline: 2985,
            uncertainty: 500,
            pool: "classical",
        });
    });
});

