type PoolGolden = {
    estimate: { rating: number; uncertainty: number; pool: StrengthPool };
    games: number;
    accuracy: number;
    aggFeature: number;
    effMoves: number;
};
type PhaseGolden = {
    estimate: { rating: number; uncertainty: number };
    moves: number;
    accuracy: number;
    aggFeature: number;
    effMoves: number;
};

function expectProfile(
    actual: ReturnType<typeof aggregateProfile>,
    expected: {
        primaryPool: StrengthPool;
        pools: Partial<Record<StrengthPool, PoolGolden>>;
        phases: Record<StrengthPhase, PhaseGolden>;
        recent: { key: string; rating: number; pool: StrengthPool }[];
    },
) {
    expect(actual.totalGames).toBe(4);
    expect(actual.primaryPool).toBe(expected.primaryPool);
    expect(Object.keys(actual.pools).sort()).toEqual(Object.keys(expected.pools).sort());
    for (const [pool, golden] of Object.entries(expected.pools) as [StrengthPool, PoolGolden][]) {
        const profile = actual.pools[pool];
        expect(profile).toBeDefined();
        expect(profile?.pool).toBe(pool);
        expect(profile?.games).toBe(golden.games);
        expect(profile?.estimate).toEqual(golden.estimate);
        close(profile?.accuracy, golden.accuracy);
        close(profile?.aggFeature, golden.aggFeature);
        close(profile?.effMoves, golden.effMoves);
    }
    for (const [phase, golden] of Object.entries(expected.phases) as [
        StrengthPhase,
        PhaseGolden,
    ][]) {
        const profile = actual.phases[phase];
        expect(profile).toBeDefined();
        expect(profile?.phase).toBe(phase);
        expect(profile?.moves).toBe(golden.moves);
        expect(profile?.estimate).toEqual(golden.estimate);
        close(profile?.accuracy, golden.accuracy);
        close(profile?.aggFeature, golden.aggFeature);
        close(profile?.effMoves, golden.effMoves);
    }
    expect(actual.recent.map((r) => r.entry.key)).toEqual(expected.recent.map((r) => r.key));
    expect(actual.recent.map((r) => r.estimate?.rating)).toEqual(
        expected.recent.map((r) => r.rating),
    );
    expect(actual.recent.map((r) => r.estimate?.pool)).toEqual(expected.recent.map((r) => r.pool));
}

