describe("statsOpeningBook", () => {
    test("lazy book is a shared singleton", async () => {
        const first = await getOpeningBook();
        const second = await getOpeningBook();
        expect(second).toBe(first);
        expect(first.length).toBe(3733);
    });

    test("matchBook matches review-core prefix semantics", async () => {
        const book = await getOpeningBook();
        expect(matchBook(["e4", "e5", "Nf3", "Nc6", "Bb5", "a6"], book)).toEqual({
            plies: 6,
            eco: "C70",
            name: "Ruy Lopez: Morphy Defense",
        });
        // Prefix continues past the deepest complete line ("e4 g5" = Borg Defense,
        // "e4 g5 d4" is only a prefix of longer lines, "f6" leaves book).
        expect(matchBook(["e4", "g5", "d4", "f6"], book)).toEqual({
            plies: 3,
            eco: "B00",
            name: "Borg Defense",
        });
        expect(matchBook(["d4", "Nf6", "c4", "g6", "Nc3", "Bg7", "e4", "d6"], book)).toEqual({
            plies: 8,
            eco: "E70",
            name: "King's Indian Defense: Normal Variation",
        });
        expect(matchBook(["h4", "h5", "a4"], book)).toEqual({
            plies: 1,
            eco: "A00",
            name: "Kádas Opening",
        });
        expect(matchBook([], book)).toEqual({ plies: 0, eco: null, name: null });
    });
});

